import json

W = "https://en.wiktionary.org/wiki/"
TAOS = W + "ταώς"
PAVO = W + "pavo"
PEACOCK = W + "peacock"
TAVUS = W + "طاووس"
TOKAI = W + "தோகை"
TREYES = W + "Reconstruction:Proto-Indo-European/tréyes"
SITAR = W + "sitar"
GUITAR = W + "guitar"
KITHARA = W + "κιθάρα"
TESTIS = W + "testis"
TRIBUS = W + "tribus"
THRIZ = W + "Reconstruction:Proto-Germanic/þrīz"
SE = W + "سه"
GUITARRA = W + "guitarra"
SETAR = W + "سه‌تار"
TERTIUS = W + "tertius"
AB_GITAR = "https://abadis.ir/fatofa/گیتار/"
AB_TAVUS = "https://abadis.ir/fatofa/طاووس/"

# ---------- shared reference checks ----------
KLN_PEACOCK = {"ref": "KLN:1143", "status": "partial", "note": "Klein 1966 s.v. peacock (KLN_1966.txt line 27770): 'OE. pāwa, pēa ... fr. L. pāvo, gen. pāvonis, 'peacock' ... which, together with Gk. ταώς, prob. comes ult. fr. Tamil tokei, tōgei (whence also Heb. tukkiyyim, 'peacocks'). The initial p- in L. pavo is due to imitative influence'. Klein supports the Tamil root and the Latin/OE/English chain, but routes Latin and Greek directly from the eastern source, not through Persian/Arabic, and has no Sanskrit link."}
SKT_PEACOCK = {"ref": "SKT:378", "status": "supports", "note": "Skeat, Concise Etym. Dict. s.v. Peacock (SKT_dli_revised.txt line 55507): '(L. - Pers. - Tamil; and E.) M.E. pecok ... AS. pea, pāwa; all from L. pāuo ... The same as Gk. ταώς, for ταϝώς, a peacock; the change from τ to p being due to the fact that the word was foreign both to L. and Gk. - Pers. tāwus, tāus, a peacock. - Tamil tōkei, tōgei, a peacock'. This is exactly Nourai's chain (Tamil > Persian > Greek/Latin > OE > E.); it is Skeat's 1911 view, now abandoned."}
BQT1346 = {"ref": "BQT:1346", "status": "partial", "note": "Borhan-e Qate' p.1346 (BQT_v3_picofile.pdf page 139; the tool's default offset lands on pdf 141, use --pdf-page 139; transcription saved in ocr/BQT/1346.vision.txt), Mo'in's footnote s.v. طاوس: '(عر) معرب آن طویس، یونانی Taôs، آرامی طاوسا tausâ «تسیمرن. لغات دخیل اکدی ص۵۲» طبق تحقیق استاد پور داود اصل کلمه از زبان دراویدی وارد سانسکریت شده و از آنجا بزبانهای دیگر رفته'. Source of Nourai's Dravidian > Sanskrit > Arabic/Aramaic chart (after Pourdavoud); Mo'in himself lists the Greek and Aramaic forms side by side without making Greek a daughter of Persian."}
MON2203 = {"ref": "MON:2203", "status": "partial", "note": "Mo'in, Farhang-e Farsi vol.2 s.v. طاوس (MON_part1.txt line 91933): 'طاوس (طاووس) [دراویدی هندی] (اِ.) (جان.) پرنده‌ای است از راستهٔ ماکیان‌ها که اصلش از هندوستان و مالزی است'; abadis (Mo'in) s.v. طاووس: '[معر.] = طاوس'. Supports the Indian origin and the Arabic-mediated Persian form; the Aramaic tausâ is from the Borhan footnote, not this entry."}

# ---------- shared consulted ----------
C_KLN_PEACOCK = {"src": "KLN", "where": "1966 s.v. peacock (KLN_1966.txt line 27770)", "stance": "partial", "note": "'L. pavo ... which, together with Gk. ταώς, prob. comes ult. fr. Tamil tokei, tōgei (whence also Heb. tukkiyyim) ... initial p- in L. pavo is due to imitative influence; cp. L. paupulo, 'the natural sound of the peacock''."}
C_SKT_PEACOCK = {"src": "SKT", "where": "s.v. Peacock (SKT_dli_revised.txt line 55507)", "stance": "supports", "note": "'from L. pāuo ... The same as Gk. ταώς, for ταϝώς ... Pers. tāwus, tāus, a peacock. - Tamil tōkei, tōgei' (Skeat's Tamil > Persian > Greek > Latin chain)."}
C_BQT1346 = {"src": "BQT", "where": "p.1346, Mo'in fn. s.v. طاوس (ocr/BQT/1346.vision.txt)", "stance": "partial", "note": "'(عر) معرب آن طویس، یونانی Taôs، آرامی طاوسا tausâ ... اصل کلمه از زبان دراویدی وارد سانسکریت شده و از آنجا بزبانهای دیگر رفته' (after Pourdavoud)."}
C_MON_TAVUS = {"src": "MON", "where": "vol.2 s.v. طاوس (MON_part1.txt line 91933); abadis s.v. طاووس", "stance": "partial", "note": "'طاوس (طاووس) [دراویدی هندی] ... اصلش از هندوستان و مالزی است'; abadis/Mo'in s.v. طاووس '[معر.] = طاوس' (Arabicized)."}
C_ARB_TAVUS = {"src": "ARB", "where": "al-Mu'arrab (ARB_mo3rb.txt lines 16707-16712)", "stance": "partial", "note": "'(م) «طاؤوس» بالهمزة وأصلها الواو ... وقال [ابن دريد]: وطاؤوس أعجمي ... وقد تكلمت به العرب' - the Arab philologists already treated ṭāwūs as a foreign word, without naming the source."}

entries = []

# =================== ENTRY 0: Tôkei ===================
e0_nodes = [
 {
  "id": 1, "lang": "Sanskrit", "words": "", "verdict": "disputed",
  "derivation": "Empty pass-through box: Nourai (following Pourdavoud via Mo'in's Borhan footnote) routes the Tamil word through Sanskrit before it reaches Aramaic and Arabic. No Sanskrit form of the tōkai/ṭāwūs type is attested: the Sanskrit words for 'peacock' are mayūra-, śikhin-, barhin-, kalāpin-. Modern scholarship (Wiktionary s.v. ταώς, Klein s.v. peacock) derives the Mediterranean/Semitic words either from Pre-Greek ταώς or directly from a Dravidian (Tamil tōkai) or other eastern source by sea trade, with no Sanskrit intermediary.",
  "derivation_fa": "این خانهٔ خالی «سنسکریت» را نورایی به پیروی از پورداوود (در حاشیهٔ معین بر برهان قاطع) میان تامیلی و آرامی/عربی گذاشته است. اما در سنسکریت واژه‌ای از گونهٔ tōkai یا ṭāwūs برای طاووس دیده نمی‌شود؛ نام‌های سنسکریت طاووس mayūra، śikhin و barhin است. پژوهش امروزی (کلاین، ویکی‌واژه) واژهٔ یونانی ταώς را پیش‌یونانی می‌داند یا آن را مستقیم به منبعی شرقی مانند تامیلی tōkai می‌رساند، و گذر از سنسکریت را تأیید نمی‌کند.",
  "sources": [TAOS, TOKAI],
  "ref_check": [BQT1346],
  "consulted": [
   C_KLN_PEACOCK,
   {"src": "SKT", "where": "s.v. Peacock (SKT_dli_revised.txt line 55507)", "stance": "contradicts", "note": "Skeat's chain is 'Pers. tāwus ... - Tamil tōkei' with no Sanskrit stage."},
   {"src": "MON", "where": "vol.2 s.v. طاوس (MON_part1.txt line 91933)", "stance": "partial", "note": "Only the tag '[دراویدی هندی]' - Dravidian/Indian, no Sanskrit form given."}
  ]
 },
 {
  "id": 2, "lang": "Arabic", "words": "tawoos", "verdict": "disputed",
  "derivation": "Arabic ṭāwūs (طاووس, also طاؤوس) 'peacock' is real, but it is not taken from Sanskrit: it is borrowed from Aramaic ṭawsā (טַוסָא), itself borrowed from Greek ταώς (Wiktionary s.v. طاووس: 'Borrowed from Aramaic ṭawsā, borrowed from Ancient Greek ταώς, borrowed from Pre-Greek'). The emphatic ṭ- reflects the Aramaic spelling of Greek t-, and the long ū the Greek long ō. Arab lexicographers (Ibn Durayd in al-Jawālīqī's al-Mu'arrab) already call it a foreign word (أعجمي).",
  "derivation_fa": "«طاووس» عربی (طاؤوس) به معنای طاووس واژه‌ای واقعی است، اما از سنسکریت گرفته نشده است؛ ویکی‌واژه آن را وام‌واژه از آرامی ṭawsā و آن را از یونانی ταώς می‌داند. ط عربی برابر t یونانی در نوشتار آرامی است و ū بلند برابر ō بلند یونانی. ابن درید (در المعرّب جوالیقی) نیز آن را «أعجمی» شمرده است. پس اصل واژه درست است ولی مسیر «سنسکریت ← عربی» را پژوهش امروزی نمی‌پذیرد.",
  "sources": [TAVUS, TAOS],
  "ref_check": [BQT1346],
  "consulted": [C_ARB_TAVUS, C_BQT1346, C_KLN_PEACOCK]
 },
 {
  "id": 3, "lang": "Aramaic", "words": "tausâ", "verdict": "disputed",
  "derivation": "Aramaic ṭawsā / ṭāwsā (טַוסָא) 'peacock' is attested and Mo'in quotes it as tausâ (after Zimmern, Akkadische Fremdwörter p.52). Wiktionary derives it from Greek ταώς (5th c. BCE Attic), the definite ending -ā being the Aramaic emphatic state; it was the channel through which the word reached Arabic. Nourai's derivation of the Aramaic word from (an unattested) Sanskrit form is not supported; the Hebrew tukkiyyim (1 Kings 10:22), which Klein ties to Tamil tōkai, is a different word.",
  "derivation_fa": "آرامی ṭawsā (طاوسا، tausâ) «طاووس» در منابع هست و معین آن را از تسیمرن (واژه‌های دخیل اکدی، ص۵۲) نقل کرده است. ویکی‌واژه آن را از یونانی ταώς (یونانی آتیکی سدهٔ پنجم پیش از میلاد) می‌داند؛ ā پایانی نشانهٔ حالت معرفهٔ آرامی است، و همین واژه راه رسیدن طاووس به عربی بوده است. اشتقاق آن از سنسکریت پذیرفته نیست؛ واژهٔ عبری tukkiyyim (کتاب پادشاهان) که کلاین آن را با تامیلی tōkai می‌سنجد واژهٔ دیگری است.",
